// Who gets which answer. A sketch of the rules in G0-18, G0-19 and G5-14, not production code.
export type Author = "person" | "nova" | "routine";
export type Answer = "pass" | "warn" | "block" | "reject";

export const answer = (author: Author, lockedPathChanged: boolean, falseHeals: string[]): Answer => {
  if (author !== "person" && lockedPathChanged) return "block"; // locked-checks: agents never edit what judges them
  if (falseHeals.length === 0) return "pass";
  if (author === "routine") return "reject"; // unattended: nobody reads it first, so the run fails
  return "warn"; // people and Nova: an annotation the one reviewer reads
};

// A small false-heal detector for one file's patch: the shape of G0-19 and G5-14.
const TEST_FILE = /(^|\/)(tests?|e2e)\/|\.(test|spec)\.tsx?$|(^|\/)test_[^/]+\.py$/;
const ASSERT = /\bexpect\(|\bassert\b|self\.assert\w+\(/;
const SKIP = /\b(it|test|describe)\.(skip|only|fixme)\(|@pytest\.mark\.(skip|xfail)/;
const THRESHOLD = /(fail[-_]under|retries|timeout\w*)\s*[:=]\s*([\d.]+)/i;

export function falseHeals(path: string, patch: string): string[] {
  const changed = patch.split("\n").filter((l) => /^[+-]/.test(l) && !/^(\+\+\+|---)/.test(l));
  const added = changed.filter((l) => l.startsWith("+")).map((l) => l.slice(1));
  const removed = changed.filter((l) => l.startsWith("-")).map((l) => l.slice(1));
  const found = added.filter((l) => SKIP.test(l)).map((l) => `new skip: ${l.trim()}`);
  if (TEST_FILE.test(path)) {
    const lost = removed.filter((l) => ASSERT.test(l)).length - added.filter((l) => ASSERT.test(l)).length;
    if (lost > 0) found.push(`${lost} assertion(s) removed`);
  }
  for (const [key, before, after] of thresholdChanges(removed, added)) {
    if (loosened(key, before, after)) found.push(`${key} loosened ${before} -> ${after}`);
  }
  return found;
}

// Lower fail-under is looser; more retries or a longer timeout is looser.
export const loosened = (key: string, before: number, after: number): boolean =>
  key.toLowerCase().includes("fail") ? after < before : after > before;

export function thresholdChanges(removed: string[], added: string[]): Array<[string, number, number]> {
  const pairs: Array<[string, number, number]> = [];
  for (const old of removed) {
    const a = THRESHOLD.exec(old);
    if (!a) continue;
    const b = added.map((l) => THRESHOLD.exec(l)).find((m) => m?.[1].toLowerCase() === a[1].toLowerCase());
    if (b) pairs.push([a[1], Number(a[2]), Number(b[2])]);
  }
  return pairs;
}

